G=load(); print(sorted(G))

def f(inp):
    out=[row[:] for row in inp]
    H,W=len(inp),len(inp[0])
    seen=set()
    for i in range(H):
        for j in range(W):
            c=inp[i][j]
            if c==0 or (i,j) in seen: continue
            # find component size (4-conn of same color)
            stack=[(i,j)]; comp=[]
            while stack:
                a,b=stack.pop()
                if (a,b) in seen or inp[a][b]!=c: continue
                seen.add((a,b)); comp.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<H and 0<=nb<W: stack.append((na,nb))
            if len(comp)>1:
                for a,b in comp: out[a][b]=1
    return out
